const $=id=>document.getElementById(id),esc=(v='')=>String(v).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const dictionaries={gbr:['ГБР-2','ГБР-7','ГБР-12','ГБР-18','ГБР-21','ГБР-33','ГБР-52'],admins:['А 01 — Смирнов А.С.','А 02 — Иванова Е.В.','А 03 — Орлов М.Л.','А 07 — Зайцев И.Ф.','А 12 — Воронова А.О.'],managers:['Соколова Марина Викторовна','Орлова Елена Сергеевна','Крылов Андрей Игоревич','Зайцева Мария Игоревна','Мельников Павел Сергеевич'],roles:['Ответственный','Администратор','Доверенный','Сотрудник службы безопасности'],services:['ОС','ПС','КТС'],loopTypes:['Охранный','Пожарный','Технологический','Тревожная кнопка','Тампер']};
