function createObject(row,index){return {id:`obj-${row[0]}`,number:row[0],identifier:`NEVA-${row[0]}`,system:row[1],pco:'Краснодар',name:row[2],address:row[3],owner:['ООО «Нева-Юг»','ИП Иванов А.А.','ООО «Торговый дом»'][index%3],category:['2','3','5','7','10'][index%5],gbr:dictionaries.gbr[index%dictionaries.gbr.length],administrator:dictionaries.admins[index%dictionaries.admins.length],manager:dictionaries.managers[index%dictionaries.managers.length],status:'Действующий',latitude:(45.03+index/1000).toFixed(10),longitude:(38.97+index/1000).toFixed(10),orderNumber:`П-${2026000+index}`,note:'',sections:[{order:'1',name:'Основной раздел',description:'Периметр и внутренние помещения',service:index%3===0?'КТС':'ОС'}],loops:[{number:'000001',section:'1',name:'Входная дверь',description:'Магнитоконтактный извещатель',type:'Охранный'},{number:'000002',section:'1',name:'Объём',description:'Датчик движения',type:'Охранный'}],contacts:[{name:['Иванов Александр Х.','Петров Александр Ю.','Орлов Михаил Л.'][index%3],role:'Администратор',phone:['+7 (983) 825-44-27','+7 (906) 826-81-56','+7 (918) 220-41-09'][index%3],appAccess:true},{name:'Смирнова Елена В.',role:'Ответственный',phone:'+7 (919) 828-18-85',appAccess:false}],trusted:[{name:'Кузнецова Ольга В.',phone:'+7 (918) 310-22-44',addedBy:'Иванов Александр Х.',addedAt:'23.09.2026, 10:30'}],client:{name:'',phone:'',appPhone:'',channels:['Push'],types:['Тревоги и КТС']},photos:[]};}
function migrate(o,index){const system={Феникс:'F',Андромеда:'A',Мираж:'MK',M:'MK'}[o.system]||o.system||'F',fresh=createObject([o.number||'',system,o.name||'Новый объект',o.address||''],index);return {...fresh,...o,system,identifier:o.identifier||fresh.identifier,pco:o.pco||o.city||'Краснодар',owner:o.owner||fresh.owner,sections:o.sections||fresh.sections,trusted:o.trusted||[],client:o.client||fresh.client,loops:(o.loops||fresh.loops).map((l,i)=>({number:String(l.number||i+1).slice(0,6),section:String(l.section||'1'),name:l.name||`Шлейф ${i+1}`,description:l.description||'',type:l.type||l.zone||'Охранный'})),contacts:(o.contacts||fresh.contacts).map(c=>({name:c.name||'',role:c.role||'Ответственный',phone:c.phone||'',appAccess:Boolean(c.appAccess)}))};}
let objects;try{objects=(JSON.parse(localStorage.getItem('neva-admin-objects-v2'))||base.map(createObject)).map(migrate);}catch(e){objects=base.map(createObject);}let selectedId=objects[0]?.id,dragIndex=null;const form=$('objectForm');
function current(){return objects.find(o=>o.id===selectedId);}function norm(v=''){return String(v).toLowerCase().replace(/ё/g,'е').replace(/[^a-zа-я0-9]+/gi,' ').trim();}function prefixed(o){return `${o.system}${o.number}`;}function match(o,q){q=norm(q);if(!q)return true;return norm(prefixed(o)).startsWith(q)||norm(o.number).startsWith(q)||[o.name,o.address,o.owner].some(v=>norm(v).includes(q)||norm(v).split(' ').some(w=>w.startsWith(q)));}
function saveStore(){try{localStorage.setItem('neva-admin-objects-v2',JSON.stringify(objects));}catch(e){toast('Недостаточно места для сохранения файлов');}}function toast(t){$('adminToast').textContent=t;$('adminToast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('adminToast').classList.remove('show'),2200);}
function filtered(){const q=$('adminSearch').value,s=$('systemFilter').value,c=$('categoryFilter').value;return objects.filter(o=>match(o,q)&&(!s||o.system===s)&&(!c||String(o.category)===c)).sort((a,b)=>Number(a.number)-Number(b.number)||a.name.localeCompare(b.name,'ru'));}
function renderList(){const list=filtered();$('objectCount').textContent=`${list.length} из ${objects.length} объектов`;$('adminObjectList').innerHTML=list.length?list.map(o=>`<button class="admin-object-card ${o.id===selectedId?'active':''}" data-id="${esc(o.id)}"><span><b><em>${esc(o.system)}</em>${esc(o.number)} · ${esc(o.name)}</b><small>${esc(o.address)}</small></span><i>${esc(o.category)} кат.</i></button>`).join(''):'<div class="photo-empty">Объекты не найдены</div>';document.querySelectorAll('.admin-object-card').forEach(b=>b.onclick=()=>selectObject(b.dataset.id));}
function renderSuggestions(){const q=$('adminSearch').value.trim();if(!q){$('adminSuggestions').hidden=true;return;}const list=objects.filter(o=>match(o,q)).sort((a,b)=>Number(a.number)-Number(b.number)).slice(0,8);$('adminSuggestions').innerHTML=list.map(o=>`<button data-id="${esc(o.id)}"><b>${esc(o.system)}${esc(o.number)}</b> · ${esc(o.name)}<br><small>${esc(o.address)}</small></button>`).join('');$('adminSuggestions').hidden=!list.length;document.querySelectorAll('#adminSuggestions button').forEach(b=>b.onclick=()=>{$('adminSearch').value='';$('adminSuggestions').hidden=true;selectObject(b.dataset.id);});}
function selectObject(id){selectedId=id;renderList();renderEditor();}function options(values,currentValue){return values.map(v=>`<option ${v===currentValue?'selected':''}>${esc(v)}</option>`).join('');}
function renderEditor(){const o=current();if(!o)return;$('editorTitle').textContent=o.name;$('editorSubtitle').textContent=`${o.system}${o.number} • ${o.pco} • ${o.address}`;$('gbrSelect').innerHTML=options(dictionaries.gbr,o.gbr);$('administratorSelect').innerHTML=options(dictionaries.admins,o.administrator);$('managerSelect').innerHTML=options(dictionaries.managers,o.manager);[...form.elements].forEach(f=>{if(f.name)f.value=o[f.name]??'';});$('ownersList').innerHTML=[...new Set(objects.map(x=>x.owner).filter(Boolean))].map(v=>`<option value="${esc(v)}">`).join('');renderSections();renderLoops();renderContacts();renderTrusted();renderClient();renderFiles();}
function bindRows(body,key){document.querySelectorAll(`#${body} input,#${body} select`).forEach(f=>f.oninput=()=>{const row=current()[key][Number(f.closest('tr').dataset.index)];row[f.dataset.key]=f.type==='checkbox'?f.checked:f.value;});}
function renderSections(){const o=current();$('sectionsCount').textContent=o.sections.length;$('adminSectionsBody').innerHTML=o.sections.map((s,i)=>`<tr data-index="${i}"><td><input data-key="order" inputmode="numeric" value="${esc(s.order)}"></td><td><input data-key="name" value="${esc(s.name)}"></td><td><input data-key="description" value="${esc(s.description)}"></td><td><select data-key="service">${options(dictionaries.services,s.service)}</select></td><td><button class="remove-row" data-remove-section="${i}">×</button></td></tr>`).join('');bindRows('adminSectionsBody','sections');document.querySelectorAll('[data-remove-section]').forEach(b=>b.onclick=()=>{o.sections.splice(+b.dataset.removeSection,1);renderSections();renderLoops();});}
function sectionOptions(value){const nums=current().sections.map(s=>s.order);return options(nums.length?nums:['1'],value);}
function renderLoops(){const o=current();$('loopsCount').textContent=o.loops.length;$('adminLoopsBody').innerHTML=o.loops.map((l,i)=>`<tr data-index="${i}"><td><input class="loop-number" data-key="number" maxlength="6" inputmode="numeric" value="${esc(l.number)}"></td><td><select data-key="section">${sectionOptions(l.section)}</select></td><td><input data-key="name" value="${esc(l.name)}"></td><td><input data-key="description" value="${esc(l.description)}"></td><td><select data-key="type">${options(dictionaries.loopTypes,l.type)}</select></td><td><button class="remove-row" data-remove-loop="${i}">×</button></td></tr>`).join('');bindRows('adminLoopsBody','loops');document.querySelectorAll('.loop-number').forEach(f=>f.oninput=()=>{f.value=f.value.replace(/\D/g,'').slice(0,6);current().loops[+f.closest('tr').dataset.index].number=f.value;});document.querySelectorAll('[data-remove-loop]').forEach(b=>b.onclick=()=>{o.loops.splice(+b.dataset.removeLoop,1);renderLoops();});}
function contactDirectory(){const map=new Map();objects.forEach(o=>o.contacts.forEach(c=>{if(c.phone)map.set(norm(c.phone),{...c,objects:[]});}));objects.forEach(o=>o.contacts.forEach(c=>{const x=map.get(norm(c.phone));if(x)x.objects.push(o);}));return map;}
function renderContacts(){const o=current(),directory=contactDirectory();$('contactsCount').textContent=o.contacts.length;$('contactPhones').innerHTML=[...directory.values()].map(c=>`<option value="${esc(c.phone)}">${esc(c.name)}</option>`).join('');$('adminContactsBody').innerHTML=o.contacts.map((c,i)=>{const locked=(c.phone.match(/\d/g)||[]).length<10;return `<tr data-index="${i}" draggable="true"><td class="drag-handle" title="Перетащить">⋮⋮</td><td class="priority-cell">${i+1}</td><td><input data-key="phone" list="contactPhones" value="${esc(c.phone)}" placeholder="Сначала телефон"></td><td><input data-key="name" value="${esc(c.name)}" ${locked?'disabled':''}></td><td><select data-key="role" ${locked?'disabled':''}>${options(dictionaries.roles,c.role)}</select></td><td class="app-check"><input type="checkbox" data-key="appAccess" ${c.appAccess?'checked':''} ${locked?'disabled':''}></td><td><button class="info-row" data-contact-info="${i}" title="Объекты ответственного">ⓘ</button><button class="remove-row" data-remove-contact="${i}">×</button></td></tr>`;}).join('');bindRows('adminContactsBody','contacts');document.querySelectorAll('#adminContactsBody [data-key="phone"]').forEach(input=>input.oninput=()=>{const i=+input.closest('tr').dataset.index,c=o.contacts[i],known=directory.get(norm(input.value));c.phone=input.value;if(known){c.name=known.name;c.role=known.role;c.appAccess=known.appAccess;}renderContacts();setTimeout(()=>{const fields=document.querySelectorAll('#adminContactsBody [data-key="phone"]');fields[i]?.focus();fields[i]?.setSelectionRange(fields[i].value.length,fields[i].value.length);},0);});document.querySelectorAll('[data-remove-contact]').forEach(b=>b.onclick=()=>{o.contacts.splice(+b.dataset.removeContact,1);renderContacts();});document.querySelectorAll('[data-contact-info]').forEach(b=>b.onclick=()=>showPersonObjects(o.contacts[+b.dataset.contactInfo]));bindDrag();}
function bindDrag(){document.querySelectorAll('#adminContactsBody tr[draggable]').forEach(row=>{row.ondragstart=()=>{dragIndex=+row.dataset.index;row.classList.add('dragging');};row.ondragend=()=>row.classList.remove('dragging');row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();const to=+row.dataset.index;if(dragIndex===null||dragIndex===to)return;const [moved]=current().contacts.splice(dragIndex,1);current().contacts.splice(to,0,moved);dragIndex=null;renderContacts();};});}
function showPersonObjects(person){const list=objects.filter(o=>o.contacts.some(c=>norm(c.phone)===norm(person.phone)));$('ownerDialogTitle').textContent=person.name||person.phone;$('ownerObjectList').innerHTML=list.map(o=>`<button type="button" data-owner-object="${esc(o.id)}"><b>${esc(o.system)}${esc(o.number)} · ${esc(o.name)}</b><small>${esc(o.address)}</small></button>`).join('')||'<p>Другие объекты не найдены</p>';$('ownerDialog').showModal();document.querySelectorAll('[data-owner-object]').forEach(b=>b.onclick=()=>{$('ownerDialog').close();selectObject(b.dataset.ownerObject);});}
function renderTrusted(){const o=current();$('trustedCount').textContent=o.trusted.length;$('adminTrustedBody').innerHTML=o.trusted.map((t,i)=>`<tr data-index="${i}"><td><input data-key="name" value="${esc(t.name)}"></td><td><input data-key="phone" value="${esc(t.phone)}"></td><td><select data-key="addedBy">${options(o.contacts.map(c=>c.name).filter(Boolean),t.addedBy)}</select></td><td><input data-key="addedAt" value="${esc(t.addedAt)}"></td><td><button class="remove-row" data-remove-trusted="${i}">×</button></td></tr>`).join('');bindRows('adminTrustedBody','trusted');document.querySelectorAll('[data-remove-trusted]').forEach(b=>b.onclick=()=>{o.trusted.splice(+b.dataset.removeTrusted,1);renderTrusted();});}
function renderClient(){const c=current().client;$('clientName').value=c.name||'';$('clientPhone').value=c.phone||'';$('appPhone').value=c.appPhone||'';}function renderFiles(){const p=current().photos;$('adminPhotoGrid').innerHTML=p.length?p.map((src,i)=>`<figure class="admin-photo"><img src="${src}" alt="Файл ${i+1}"><button data-remove-photo="${i}">×</button></figure>`).join(''):'<div class="photo-empty">Файлы ещё не добавлены</div>';document.querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=()=>{p.splice(+b.dataset.removePhoto,1);renderFiles();});}
function saveObject(){const o=current(),data=new FormData(form);for(const [k,v] of data)o[k]=String(v).trim();o.number=o.number.replace(/\D/g,'').slice(0,10);['latitude','longitude'].forEach(k=>{const n=Number(String(o[k]).replace(',','.'));if(Number.isFinite(n))o[k]=n.toFixed(10);});o.client={...o.client,name:$('clientName').value.trim(),phone:$('clientPhone').value.trim(),appPhone:$('appPhone').value.trim()};if(!o.number||!o.name||!o.address){toast('Заполните номер, название и адрес');return;}saveStore();renderList();renderEditor();toast('Карточка сохранена');}
function openNotifications(kind){const c=current().client,isChannels=kind==='channels',values=isChannels?['Push','SMS','Телефонный звонок','E-mail']:['Тревоги и КТС','Постановка и снятие','Питание и связь','Статусы ГБР','Технические события'];$('notificationDialogTitle').textContent=isChannels?'Каналы уведомлений':'Типы уведомлений';$('notificationDialogHint').textContent=isChannels?'Куда отправлять уведомления':'Какие события получает клиент';const key=isChannels?'channels':'types';$('notificationOptions').innerHTML=values.map(v=>`<label><input type="checkbox" value="${esc(v)}" ${c[key].includes(v)?'checked':''}> ${esc(v)}</label>`).join('');$('notificationDialog').showModal();document.querySelectorAll('#notificationOptions input').forEach(i=>i.onchange=()=>{c[key]=[...document.querySelectorAll('#notificationOptions input:checked')].map(x=>x.value);});}
document.querySelectorAll('.admin-tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.admin-tabs button').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.admin-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(`tab-${b.dataset.tab}`).classList.add('active');});
$('adminSearch').oninput=()=>{renderList();renderSuggestions();};$('systemFilter').onchange=renderList;$('categoryFilter').onchange=renderList;$('saveObjectBtn').onclick=saveObject;
$('addSectionBtn').onclick=()=>{current().sections.push({order:String(current().sections.length+1),name:'',description:'',service:'ОС'});renderSections();renderLoops();};$('addLoopBtn').onclick=()=>{current().loops.push({number:'',section:current().sections[0]?.order||'1',name:'',description:'',type:'Охранный'});renderLoops();};$('addContactBtn').onclick=()=>{current().contacts.push({name:'',role:'Ответственный',phone:'',appAccess:false});renderContacts();};$('addTrustedBtn').onclick=()=>{current().trusted.push({name:'',phone:'',addedBy:current().contacts[0]?.name||'',addedAt:new Date().toLocaleString('ru-RU')});renderTrusted();};
$('newObjectBtn').onclick=()=>{const o=createObject(['','F','Новый объект',''],objects.length);o.id=`obj-${Date.now()}`;o.number='';objects.push(o);selectObject(o.id);toast('Создана новая карточка');};$('duplicateObjectBtn').onclick=()=>{const o=structuredClone(current());o.id=`obj-${Date.now()}`;o.number='';o.identifier='';o.name+=' — копия';objects.push(o);selectObject(o.id);toast('Карточка продублирована');};$('deleteObjectBtn').onclick=()=>{if(objects.length<2||!confirm(`Удалить объект «${current().name}»?`))return;objects=objects.filter(o=>o.id!==selectedId);selectedId=objects[0].id;saveStore();selectObject(selectedId);toast('Объект удалён');};
$('ownerObjectsBtn').onclick=()=>{const owner=form.elements.owner.value,list=objects.filter(o=>o.owner===owner);$('ownerDialogTitle').textContent=owner||'Владелец не указан';$('ownerObjectList').innerHTML=list.map(o=>`<button type="button" data-owner-object="${esc(o.id)}"><b>${esc(o.system)}${esc(o.number)} · ${esc(o.name)}</b><small>${esc(o.address)}</small></button>`).join('')||'<p>Объекты не найдены</p>';$('ownerDialog').showModal();document.querySelectorAll('[data-owner-object]').forEach(b=>b.onclick=()=>{$('ownerDialog').close();selectObject(b.dataset.ownerObject);});};
$('fillByOrderBtn').onclick=()=>{const value=$('orderNumber').value.trim();if(!value){toast('Введите номер приказа');return;}const o=current();o.orderNumber=value;o.identifier=o.identifier||`ORD-${value.replace(/\W/g,'')}`;o.pco=o.pco||'Краснодар';o.sections.length||o.sections.push({order:'1',name:'Основной раздел',description:'',service:'ОС'});renderEditor();toast('Данные приказа подставлены в карточку');};
document.querySelectorAll('input[name="latitude"],input[name="longitude"]').forEach(i=>i.onblur=()=>{const n=Number(i.value.replace(',','.'));if(Number.isFinite(n))i.value=n.toFixed(10);});$('channelsBtn').onclick=()=>openNotifications('channels');$('notificationTypesBtn').onclick=()=>openNotifications('types');
$('objectPhotoInput').onchange=e=>{[...e.target.files].slice(0,5).forEach(file=>{if(file.size>1500000){toast('Файл должен быть меньше 1,5 МБ');return;}const r=new FileReader();r.onload=()=>{current().photos.push(r.result);renderFiles();};r.readAsDataURL(file);});e.target.value='';};
